@router.post("/experiments/{experiment_key}/conversion")
async def track_experiment_conversion(
    experiment_key: str,
    payload: ExperimentConversionPayload,
    current_user: User = Depends(get_current_user)
):
    if payload.target_user_key != str(current_user.id) and not current_user.is_admin:
        raise HTTPException(status_code=403, detail="Forbidden: cannot submit experiment conversions for another user")

    context = Context.builder(str(current_user.id)).kind("user").build()
    ldclient.get().track(
        event_name=f"conversion_{experiment_key}",
        context=context,
        metric_value=payload.revenue_value
    )
    return {"status": "conversion_recorded", "user_key": str(current_user.id)}
